def next_greater(values):
    """
    Returns a list where each position holds the first value to its right that is strictly greater,
    or None if there is none. Handles empty input.
    """
    if not values:
        return []

    result = []
    stack = []

    for value in values:
        while stack and stack[-1] < value:
            stack.pop()
        if not stack:
            result.append(None)
        else:
            result.append(stack[-1])
        stack.append(value)

    return result
